export const BODY: string = "\n<p>ویب امیج آپٹیمائزر وہ ٹول ہے جو تصویر کو ویب کے لیے تیار کرتا ہے: درست سائز، درست فارمیٹ، درست معیار۔ ویب کی تصویر وہی اچھی ہے جو تیز لوڈ ہو اور صاف نظر آئے۔</p>\n<p>ویب تصویر کی غلطی ویب سائٹ کو سست کر دیتی ہے۔ بڑی تصویر صفحہ کو دیر سے لوڈ کرتی ہے، اور سست صفحہ زائر کو بھگا دیتا ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ پری سیٹ کیا ہیں، ہیرو اور پروڈکٹ تصویر کیسے تیار کریں، اور لیزی لوڈنگ کیا ہے۔ استعمال کے لیے <a href=\"/ur/website-ke-liye-tasveer-optimize-karein/\">ویب امیج آپٹیمائزر</a> کھولیں۔</p>\n<h2 id=\"what-is-web-optimisation\">ویب آپٹیمائزیشن کیا ہے؟</h2>\n<p>ویب آپٹیمائزیشن تصویر کو ویب کے لیے چھوٹا اور تیز بنانا ہے، بغیر معیار گرے۔ یہ سائز، فارمیٹ اور معیار کا توازن ہے۔</p>\n<p>ویب آپٹیمائزیشن اس لیے اہم ہے کہ ویب سائٹ کی رفتار گوگل کی رینکنگ میں شمار ہوتی ہے۔ تیز سائٹ اوپر آتی ہے۔</p>\n<p>ویب آپٹیمائزیشن کا مطلب تصویر کو چھوٹا کرنا نہیں، بلکہ اسے درست بنانا ہے۔ درست تصویر تیز بھی ہے اور صاف بھی۔</p>\n<h2 id=\"presets-explained\">پری سیٹ کی وضاحت</h2>\n<p>پری سیٹ تیار شدہ ترتیب ہے، جیسے ہیرو، پروڈکٹ یا تھمب نیل۔ ہر پری سیٹ میں سائز، فارمیٹ اور معیار طے ہوتا ہے۔</p>\n<p>پری سیٹ سے وقت بچتا ہے: آپ کو ہر بار سائز نہیں سوچنا پڑتا۔ پری سیٹ چنیں اور تصویر تیار ہے۔</p>\n<p>پری سیٹ کو اپنی ضرورت کے مطابق بدل بھی سکتے ہیں۔ پری سیٹ شروعات ہے، حتمی فیصلہ آپ کا ہے۔</p>\n<h2 id=\"hero-images\">ہیرو تصویر</h2>\n<p>ہیرو تصویر صفحے کی سب سے بڑی تصویر ہے، جو سب سے پہلے نظر آتی ہے۔ اسے تیز اور صاف ہونا چاہیے۔</p>\n<p>ہیرو تصویر کے لیے 1600 پکسلز چوڑائی کافی ہے۔ اس سے بڑی تصویر فائل کو بھاری کر دیتی ہے، بغیر فائدہ دیے۔</p>\n<p>ہیرو تصویر پر لیزی لوڈنگ نہ لگائیں، کیونکہ وہ سب سے پہلے نظر آتی ہے۔ لیزی لوڈنگ اسے دیر سے دکھاتی ہے۔</p>\n<h2 id=\"product-images\">پروڈکٹ تصویر</h2>\n<p>پروڈکٹ تصویر میں تفصیل اہم ہے، کیونکہ گاہک تصویر سے خریدتا ہے۔ پروڈکٹ تصویر کا معیار زیادہ رکھیں۔</p>\n<p>پروڈکٹ تصویر کے لیے 1200 پکسلز چوڑائی کافی ہے۔ اس سے گاہک زوم کر کے تفصیل دیکھ سکتا ہے۔</p>\n<p>پروڈکٹ تصویر کا پس منظر صاف رکھیں، تاکہ پروڈکٹ نمایاں ہو۔ پس منظر کی تفصیل گاہک کو الجھاتی ہے۔</p>\n<h2 id=\"cards-thumbnails\">کارڈ اور تھمب نیل</h2>\n<p>کارڈ اور تھمب نیل چھوٹی تصویریں ہیں، جو فہرست میں نظر آتی ہیں۔ ان کا سائز چھوٹا رکھیں، تاکہ صفحہ تیز لوڈ ہو۔</p>\n<p>تھمب نیل کے لیے 400 پکسلز چوڑائی کافی ہے۔ اس سے بڑا تھمب نیل فائل کو بھاری کر دیتا ہے۔</p>\n<p>تھمب نیل میں تفصیل کم ہوتی ہے، اس لیے معیار تھوڑا کم رکھ سکتے ہیں۔ چھوٹی تصویر میں معیار کا فرق نظر نہیں آتا۔</p>\n<h2 id=\"copy-img-button\">کاپی امیج بٹن</h2>\n<p>کاپی امیج بٹن سے تصویر کو براہ راست کاپی کیا جا سکتا ہے، بغیر ڈاؤن لوڈ کیے۔ یہ بلاگ اور دستاویز کے لیے کام آتا ہے۔</p>\n<p>کاپی کرنے سے پہلے تصویر کا سائز جانچیں۔ بڑی تصویر کاپی کرنے میں دیر لگتی ہے۔</p>\n<p>کاپی امیج بٹن کا استعمال آسان ہے: بٹن دبائیں اور تصویر کلپ بورڈ میں آ جاتی ہے۔</p>\n<h2 id=\"lazy-loading\">لیزی لوڈنگ کیا ہے؟</h2>\n<p>لیزی لوڈنگ کا مطلب ہے کہ تصویر صرف اس وقت لوڈ ہو جب وہ اسکرین پر آئے۔ نیچے کی تصویریں بعد میں لوڈ ہوتی ہیں۔</p>\n<p>لیزی لوڈنگ سے صفحہ تیزی سے کھلتا ہے، کیونکہ شروع میں صرف اوپر کی تصویریں لوڈ ہوتی ہیں۔</p>\n<p>لیزی لوڈنگ ہیرو تصویر پر نہ لگائیں۔ ہیرو سب سے پہلے نظر آتا ہے، اسے فوراً لوڈ ہونا چاہیے۔</p>\n<h2 id=\"formats-web\">ویب کے لیے فارمیٹ</h2>\n<p>ویب کے لیے WebP بہترین ہے، کیونکہ وہ چھوٹی فائل میں اچھا معیار دیتا ہے۔ JPG دوسرا انتخاب ہے، جو ہر جگہ کھلتا ہے۔</p>\n<p>شفاف تصویر کے لیے PNG چنیں۔ WebP بھی شفافیت رکھتا ہے، مگر پرانے براؤزر میں نہیں کھلتا۔</p>\n<p>فارمیٹ چننے میں منزل دیکھیں: ویب کے لیے WebP، ای میل کے لیے JPG، شفاف کے لیے PNG۔</p>\n<h2 id=\"quality-slider\">کوالٹی سلائیڈر</h2>\n<p>کوالٹی سلائیڈر معیار کو 0 سے 100 تک بدلتا ہے۔ 80 فیصد معیار ویب کے لیے بہترین توازن ہے۔</p>\n<p>کوالٹی 80 سے کم کرنے پر فائل چھوٹی ہوتی ہے، مگر معیار گرنے لگتا ہے۔ 80 سے اوپر فائل بڑی ہوتی ہے، بغیر نمایاں فائدہ دیے۔</p>\n<p>کوالٹی آزمانے کے لیے تصویر کو 80 پر کمپریس کریں اور دیکھیں۔ اگر صاف لگے تو وہی رکھیں۔</p>\n<h2 id=\"exif-stripping\">EXIF ہٹانا</h2>\n<p>EXIF تصویر کے اندر چھپی معلومات ہے، جیسے مقام اور کیمرہ۔ ویب پر EXIF ہٹانا چاہیے، کیونکہ وہ رازداری کا خطرہ ہے۔</p>\n<p>EXIF ہٹانے سے فائل بھی چھوٹی ہوتی ہے۔ ویب تصویر میں EXIF کی ضرورت نہیں۔</p>\n<p>ویب آپٹیمائزر EXIF خود ہٹاتا ہے۔ آپ کو الگ سے کچھ نہیں کرنا پڑتا۔</p>\n<h2 id=\"batch-web\">ویب کے لیے بیچ</h2>\n<p>بیچ میں کئی تصویروں کو ایک ساتھ ویب کے لیے تیار کیا جا سکتا ہے۔ یہ پوری ویب سائٹ کے لیے کام آتا ہے۔</p>\n<p>بیچ میں سب تصویروں پر ایک ہی پری سیٹ لگائیں، تاکہ سب یکساں ہوں۔ بیچ کا نتیجہ ZIP میں ملتا ہے۔</p>\n<p>بیچ سے پہلے ایک تصویر آزمائیں۔ اگر وہ درست ہو تو پوری بیچ چلائیں۔</p>\n<h2 id=\"og-images\">اوپن گراف تصویر</h2>\n<p>اوپن گراف تصویر وہ ہے جو سوشل میڈیا پر لنک شیئر کرنے پر نظر آتی ہے۔ اس کا سائز 1200 بائی 630 پکسلز ہونا چاہیے۔</p>\n<p>اوپن گراف تصویر میں متن بڑا رکھیں، کیونکہ وہ چھوٹی دکھائی دیتی ہے۔ چھوٹا متن پڑھا نہیں جاتا۔</p>\n<p>اوپن گراف تصویر JPG میں رکھیں، کیونکہ سوشل پلیٹ فارم JPG کو ترجیح دیتے ہیں۔</p>\n<h2 id=\"retina-web\">ریٹینا اور ویب</h2>\n<p>ریٹینا اسکرین زیادہ پکسلز مانگتی ہے، اس لیے ویب تصویر کو 2 گنا سائز میں بنائیں۔ 800 پکسلز جگہ کے لیے 1600 پکسلز تصویر بنائیں۔</p>\n<p>ریٹینا کے لیے بڑی تصویر فائل کو بھاری کر دیتی ہے، مگر معیار کے لیے ضروری ہے۔ توازن رکھیں۔</p>\n<p>ریٹینا تصویر کی جانچ کے لیے اسے ریٹینا اسکرین پر دیکھیں۔ عام اسکرین پر فرق نظر نہیں آتا۔</p>\n<h2 id=\"alt-text-web\">آلٹ ٹیکسٹ اور ویب</h2>\n<p>آلٹ ٹیکسٹ تصویر کی تحریری وضاحت ہے، جو اسکرین ریڈر پڑھتا ہے۔ ہر ویب تصویر کو آلٹ ٹیکسٹ دیں۔</p>\n<p>آلٹ ٹیکسٹ SEO کے لیے بھی اہم ہے۔ گوگل آلٹ ٹیکسٹ سے تصویر کو سمجھتا ہے۔</p>\n<p>آلٹ ٹیکسٹ مختصر اور درست رکھیں۔ تصویر میں کیا ہے، وہی لکھیں۔</p>\n<h2 id=\"cdn-caching\">سی ڈی این اور کیشنگ</h2>\n<p>سی ڈی این تصویر کو دنیا بھر کے سرور پر رکھتا ہے، تاکہ وہ ہر جگہ سے تیزی سے ملے۔ سی ڈی این ویب سائٹ کو تیز کرتا ہے۔</p>\n<p>کیشنگ کا مطلب ہے کہ تصویر ایک بار لوڈ ہو کر براؤزر میں محفوظ ہو جاتی ہے۔ دوبارہ آنے پر وہ فوراً کھلتی ہے۔</p>\n<p>سی ڈی این اور کیشنگ کے لیے تصویر کا نام مستحکم رکھیں۔ نام بدلنے سے کیش ختم ہو جاتا ہے۔</p>\n<h2 id=\"webp-fallback\">WebP کا فال بیک</h2>\n<p>WebP پرانے براؤزر میں نہیں کھلتا، اس لیے فال بیک رکھیں: WebP کے ساتھ JPG بھی دیں۔ پرانا براؤزر JPG کھولے گا۔</p>\n<p>فال بیک سے ویب سائٹ ہر جگہ کام کرتی ہے۔ نیا براؤزر WebP لیتا ہے، پرانا JPG۔</p>\n<p>فال بیک کا طریقہ یہ ہے کہ HTML میں دونوں فارمیٹ لکھیں۔ براؤزر خود چن لیتا ہے۔</p>\n<h2 id=\"measuring-web\">ویب کی پیمائش</h2>\n<p>ویب کی پیمائش کے لیے صفحے کی لوڈنگ رفتار ناپیں۔ تیز صفحہ 2 سیکنڈ سے کم میں کھلتا ہے۔</p>\n<p>پیمائش کے لیے گوگل کا PageSpeed ٹول استعمال کریں۔ وہ بتاتا ہے کہ کون سی تصویر سست کر رہی ہے۔</p>\n<p>پیمائش کے بعد سب سے بڑی تصویر کو پہلے درست کریں۔ ایک بڑی تصویر پورے صفحے کو سست کر دیتی ہے۔ مزید تفصیل <a href=\"/ur/blog/tasveer-optimization-core-web-vitals/\">کور ویب وائٹلز اور تصویر کی اصلاح</a> میں اور ویب سائٹ کی رفتار کے طریقے <a href=\"/ur/blog/website-speed-ke-liye-tasveer-kaise-optimize-karein/\">ویب سائٹ کی رفتار کے لیے تصویر کی اصلاح</a> میں دیکھیں۔</p>\n";

